def pt(n): return f'PHP {n*TWD:,.0f}'
def pu(n): return f'PHP {n*USD:,.0f}'
def mtd(n): return f'NT$ {n:,.0f} / {pt(n)}'
def mus(n): return f'US$ {n:,.2f} / {pu(n)}'
def e(x): return escape(str(x)).replace('\n','<br/>')

