def para(x,style='Bodyx'): return Paragraph(e(x),s[style])
def link(url): return Paragraph(f'<link href="{escape(url)}" color="#125A9C">{e(url)}</link>',s['Smallx'])
def table(head,rows,widths):
    d=[[Paragraph(e(h),s['Headx']) for h in head]]
    for row in rows: d.append([v if isinstance(v,Paragraph) else Paragraph(e(v),s['Smallx']) for v in row])
    t=Table(d,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#1C526F')),('GRID',(0,0),(-1,-1),.25,HexColor('#C8D5DE')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,HexColor('#F5F8FA')])]))
    return t
def box(title,body,color='#E8F2F6'):
    t=Table([[Paragraph(f'<b>{e(title)}</b><br/>{e(body)}',s['Bodyx'])]],colWidths=[7.05*inch])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),HexColor(color)),('BOX',(0,0),(-1,-1),.6,HexColor('#B8CBD6')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    return t
def sec(title,intro=None):
    x=[Paragraph(e(title),s['H1x']),HRFlowable(width='100%',thickness=.7,color=HexColor('#C7D5DF'),spaceAfter=6)]
    if intro:x.append(para(intro))
    return x
def opt(rows,title='Options sorted by total published/reference cost'):
    x=[Paragraph(e(title),s['H2x'])]
    x.append(table(['ID / type','Route or service','Schedule / duration','Fare / 5-person cost','Timing, baggage and caveats','Status'],[[r[0],r[1],r[2],r[3],r[4],r[5]] for r in rows],[.63*inch,1.46*inch,1.28*inch,1.12*inch,1.72*inch,.84*inch]))
    x.append(Spacer(1,6)); return x
def footer(c,doc):
    c.saveState(); c.setStrokeColor(HexColor('#D7E1E7')); c.line(.55*inch,.47*inch,7.95*inch,.47*inch); c.setFont('Helvetica',6.7); c.setFillColor(HexColor('#607584')); c.drawString(.58*inch,.30*inch,'AeroGo Travel & Tours | Transportation research only | Observed 22 Sep 2026'); c.drawRightString(7.95*inch,.30*inch,f'Page {doc.page}'); c.restoreState()

