story += [Paragraph('Taipei pass comparison',s['H2x']),table(['Pass','Coverage','Published price','5-person reference','Limit'],[['PASS01','MRT 24h','NT$180/person','NT$900 / '+pt(900),'MRT only.'],['PASS02','MRT 48h','NT$280/person','NT$1,400 / '+pt(1400),'MRT only.'],['PASS03','Sightseeing Bus 24h','NT$660/person','NT$3,300 / '+pt(3300),'Red/Blue route hours.'],['PASS04','Sightseeing Bus 4h','NT$330/person','NT$1,650 / '+pt(1650),'Not point-to-point taxi.']],[.8*inch,1.7*inch,1.35*inch,1.35*inch,1.85*inch]),Spacer(1,5),para('Official Taipei MRT sources show single rides generally NT$20-65, first trains around 06:00 and last trains around midnight. City bus full fare is NT$15 per section; age 12 is treated full.','Note'),PageBreak()]

story += sec('7. Northern Taiwan transportation','Yehliu, Jiufen, Shifen and Shifen Waterfall are shown as independent public choices and separate guided shared products. Guided products are not directly comparable with a basic fare.') + opt(sorted(NT,key=lambda r:r[3]))
story += [Paragraph('Northern route constraints',s['H2x']),table(['Destination','Evidence','Limitation'],[['Yehliu','716; official page recommends 862/863 weekdays','716 is weekends only in Nov-Apr; Nov 19 is Thursday.'],['Jiufen','965; TRA/bus combinations','Return frequency and stop choice must be checked.'],['Shifen','795 or TRA via Ruifang + Pingxi','Transfer and local walk matter.'],['Shared tours','Klook, Trip.com, GYG, Viator','Transport plus sightseeing; fees may be extra.']],[1.0*inch,2.65*inch,3.4*inch]),Spacer(1,5),box('Shopping-stop rule','Core transport options have no shopping presentation requirement in cited operator terms. The shared sightseeing listings showed attraction stops rather than mandatory retail stops, but exact voucher itineraries still require verification.'),PageBreak()]

story += sec('8. Taichung transportation','Transport references for the requested Taichung attractions only. No multi-stop route is designed.') + opt(LOCAL[8:],'Taichung local options - public fare references')
